import React, { ReactElement } from 'react';
import {
    BaseButton,
    createStyles,
    DynamicHeader,
    IArrowLeft,
    ISupport,
    PortalManager,
    useTheme,
    IDelete,
    BottomSheetManager,
    LoadingBlockerView,
} from '@core/ui';
import { Image, Linking, Text, View } from 'react-native';
import { NavigationProp, useNavigation } from '@react-navigation/native';
import { MainStackParamList } from '@presentation/navigation/MainNavigator.tsx';
// import { HDBankLogo, IHDBank, IMessenger, IZalo } from '@src/assets/icons';
import { SUPPORT_CHANNELS } from '@src/config';
import CallSupport from '@presentation/components/header/CallSupport.tsx';
import {
    HeaderProgress,
    HeaderProgressProps,
} from '@presentation/components/header/HeaderProgress.tsx';
import { ColorValue } from 'react-native/Libraries/StyleSheet/StyleSheet';
import getImg from '@src/utils/getImg';

export interface AppHeaderProps {
    themeColor?: ColorValue;
    back?: boolean;
    support?: boolean;
    title?: string;
    logo?: boolean;
    progress?: HeaderProgressProps;
    leftComponent?: ReactElement;
    logoComponent?: ReactElement;
    isUseCloseIcon?: boolean;
    customGoBack?: () => void;
}

const CustomHeader: React.FC<AppHeaderProps> = ({
    themeColor,
    back = true,
    support = true,
    title,
    logo,
    progress,
    leftComponent,
    logoComponent,
    isUseCloseIcon = false,
    customGoBack,
}) => {
    const { theme } = useTheme();
    const styles = useStyles();
    const navigation = useNavigation<NavigationProp<MainStackParamList>>();

    const supportOptions = [
        {
            icon: '/assets/images/icons/icon_call.png',
            text: 'hotline',
            onPress: () => Linking.openURL(SUPPORT_CHANNELS.CALL_CENTER),
        },
        {
            icon: '/assets/images/icons/icon_chat.png',
            text: 'bank',
            onPress: () => {
                // TODO: Open the Chat Screen
            },
        },
        {
            icon: '/assets/images/icons/icon_zalo.png',
            text: 'zalo',
            onPress: () => Linking.openURL(SUPPORT_CHANNELS.ZALO),
        },
        {
            icon: '/assets/images/icons/icon_mess.png',
            text: 'messenger',
            onPress: () => Linking.openURL(SUPPORT_CHANNELS.MESSENGER),
        },
    ];

    return (
        <DynamicHeader
            LeftComponent={
                !back
                    ? () => <>{leftComponent}</>
                    : () => (
                        <BaseButton
                            onPress={() => {
                                customGoBack ? customGoBack() : navigation.goBack();
                            }}
                        >
                            {isUseCloseIcon ? (
                                <IDelete fill={themeColor} />
                            ) : (
                                <IArrowLeft fill={themeColor} />
                            )}
                        </BaseButton>
                    )
            }
            RightComponent={
                !support
                    ? () => <></>
                    : () => (
                        <BaseButton
                            onPress={() => {
                                // BottomSheetManager.show(
                                //     {
                                //         render: () => (
                                //             <CallSupport options={supportOptions} />
                                //         )
                                //     }
                                // )
                                PortalManager.present(() => {
                                    // console.log('render portal manager');
                                    // return <CallSupport options={supportOptions} />
                                    return <CallSupport options={supportOptions} />
                                })
                            }}
                        >
                            <ISupport fill={themeColor} />
                        </BaseButton >
                    )
            }
            MainComponent={() => (
                <View style={styles.mainContainer}>
                    {title && <Text style={styles.title}>{title}</Text>}
                    {/* {logo && <Image source={require('@src/assets/images/HDBankLogo.png')} style={styles.mainLogo} />} */}
                    {logoComponent}
                    {progress && (
                        <HeaderProgress
                            current={progress.current}
                            total={progress.total}
                            colors={{
                                previous: theme.Colors.Main.Red,
                                active: theme.Colors.Main.Red,
                                next: theme.Colors.Background.Neutral500,
                            }}
                        />
                    )}
                </View>
            )}
        />
    );
};

const useStyles = createStyles((theme) => ({
    mainContainer: {
        flex: 1,
        alignItems: 'center',
        justifyContent: 'center',
        gap: theme.Size.Horizontal.Regular,
        height: theme.Size.Vertical.xxxLarge,
    },
    mainLogo: {
        height: theme.Size.Vertical.xLarge,
        resizeMode: 'contain',
        marginTop: theme.Scaling.vs(4)
    },
    title: {
        ...theme.Typography.Title300.SemiBold,
    },
}));

export default CustomHeader;
