import { createSlice } from '@reduxjs/toolkit';
import moment from 'moment';
import {
    fetchGenerateContract,
    fetchGetInitLoanProposal,
    fetchGetListCurrentAccounts,
    fetchInitLoanProposal,
    fetchSubmitLoanProposal,
    fetchProductStatus,
    fetchResendOTP,
} from './thunk';
import type { IAccount } from '@src/domain/entities/loan_collateral/depositAccount';
import type { Product, CustomerInfo, LoanPurpose, InterestConfig } from '@src/domain/entities/loan_collateral/get_init_loan_proposal';
import type { IBranch } from '@src/domain/entities/common/branch';
import type { ICurrentAccount } from '@src/domain/entities/loan_collateral/get_list_current_accounts';
import dataBranch from './mockdata/dataBranch';
import { COUNTER } from '@src/utils/constants';
import type { InitLoanProposalResponse } from '@src/domain/entities/loan_collateral/init_loan_proposal';
import type { GenerateContractResponse } from '@src/domain/entities/loan_collateral/generate_contract';
import type { ProductStatusResponse } from '@src/domain/entities/loan_product/product_status';
import type { SubmitLoanProposalResponse } from '@src/domain/entities/loan_collateral/submit_loan_proposal';
import type { ResendOTPResponse } from '@src/domain/entities/loan_collateral/resend_otp';
import { formatMoney } from '@src/utils/currency';

interface IState {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    queue: Record<string, string>;
    api: {
        productStatus?: ProductStatusResponse;
        generateContract?: GenerateContractResponse;
        initLoanProposal?: InitLoanProposalResponse;
        resendOTP?: ResendOTPResponse;
        submitLoanProposal?: SubmitLoanProposalResponse;
    };
    account: IAccount;
    loanPurpose: LoanPurpose;
    product?: Product;
    customerInfo: CustomerInfo | {};
    loanAmount: number;
    email: string;

    maturityDate: string;
    disbursementDate: string;

    branches: IBranch[];
    branchId: string;
    branchSelected: IBranch;
    intRate: string;
    availableOutstanding: number;

    paymentAcct: string;
    currentAccounts: ICurrentAccount[];

    subDate: number;
    loanIntRate: number;
    depositRateMethod: string;
    depositRateMethodDesc: string;
    intExpected: number;
    loanValue: number;
    productCode: string;
    minAmount: number;
    maxAmount: number;
    minInterestRate: number;
    maxInterestRate: number;
    interestConfigs: InterestConfig[];
    phoneNumber: string;
    pdfBase64: string;
    contractNo: string;
    isCounter: boolean;

    isDoneFetchGetInitLoanProposal: boolean;
}

const initialState: IState = {
    status: 'idle',
    error: '',
    queue: {},
    api: {},

    account: {
        accountNo: '',
        maturityDate: '',
        balance: '',
        maturityBalance: '',
        ccy: '',
        collatCode: '',
        paymentAcct: '',
        intRate: '',
        depositAcctAccruedAmt: '',
        interestAtm: '',
        hasDeposit: '',
        hasRestraint: '',
        openMethod: '',
    },
    loanPurpose: {
        loanPurposeId: '',
        loanPurposeName: '',
        loanPurposeDesc: '',
    },
    // product: {},
    customerInfo: {},

    loanAmount: 0,
    email: '',

    maturityDate: '', // ngày đến hạn trả nợ
    disbursementDate: '', // ngày nhận nợ giải ngân

    branches: dataBranch,
    branchId: '',
    branchSelected: {
        stateId: '',
        stateName: '',
        branchId: '',
        branchName: '',
    },
    intRate: '',
    availableOutstanding: 0,

    paymentAcct: '', // tài khoản nhận nợ giải ngân
    currentAccounts: [], // danh sách tài khoản nhận nợ giải ngân

    subDate: 0,
    loanIntRate: 0.0, // lãi suất vay vốn dự kiến
    depositRateMethod: '', //
    depositRateMethodDesc: '', // phương thức trả nợ
    intExpected: 0, // lãi vay dự kiến
    loanValue: 0, // gốc và lãi vay khi đến hạn
    productCode: '',
    minAmount: 0,
    maxAmount: 0,
    minInterestRate: 0,
    maxInterestRate: 0,
    interestConfigs: [],
    phoneNumber: '',
    pdfBase64: '',
    contractNo: '', // mã hợp đồng

    isCounter: false,

    isDoneFetchGetInitLoanProposal: false,
};

const slice = createSlice({
    name: 'collateralConfirm',
    initialState,
    reducers: {
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setLoanAmount: (state, { payload }) => {
            state.loanAmount = payload;

            if (state.interestConfigs.length === 0) return;

            const interestConfig = state.interestConfigs.find(
                (item) =>
                    state.subDate >= Number(item.fromLoanTime) &&
                    state.subDate < Number(item.toLoanTime) &&
                    parseFloat(payload) >= Number(item.fromAmount) &&
                    parseFloat(payload) < Number(item.toAmount),
            );

            if (!interestConfig) return;

            const config = {
                depositRateMethod: interestConfig.depositRateMethod,
                depositRateMethodDesc: interestConfig.depositRateMethodDesc,
                spreadRate:
                    interestConfig.interestType === '1'
                        ? Number(interestConfig?.spreadRate)
                        : parseFloat(interestConfig?.spreadRate) + parseFloat(state?.intRate),
            };

            if (Number(config.spreadRate) < Number(state.minInterestRate)) {
                state.loanIntRate = Number(state.minInterestRate);
            } else if (Number(config.spreadRate) > Number(state.maxInterestRate)) {
                state.loanIntRate = Number(state.maxInterestRate);
            } else {
                state.loanIntRate = Number(config.spreadRate);
            }
            state.depositRateMethod = config.depositRateMethod;
            state.depositRateMethodDesc = config.depositRateMethodDesc;

            state.intExpected = Math.ceil((((parseFloat(payload) * parseFloat(state.loanIntRate.toString())) / 100) * state.subDate) / 365);
            state.loanValue = parseFloat(payload) + parseFloat(state.intExpected?.toString());
        },
        setEmail: (state, { payload }) => {
            state.email = payload;
        },
        setPaymentAcct: (state, { payload }) => {
            state.paymentAcct = payload;
        },
        setBranch: (state, { payload }) => {
            state.branchSelected = payload;
            state.branchId = payload?.branchId;
        },
        setAccount: (state, { payload }) => {
            state.account = payload;
        },
        resetAPI: (state) => {
            state.api = {};
        },
        resetProductStatus: (state) => {
            if (state.api.productStatus) {
                // state.api.productStatus = {};
            }
        },
        setInitLoanProposal: (state) => {
            state.api.initLoanProposal = {} as InitLoanProposalResponse;
        },
    },
    extraReducers: (builder) => {
        builder
            // -----------------------------------------------------------------
            // fetchGetInitLoanProposal
            // -----------------------------------------------------------------
            .addCase(fetchGetInitLoanProposal.pending, (state) => {
                state.queue.getInitLoanProposal = 'getInitLoanProposal';
                state.status = 'loading';
                state.error = '';
                state.isDoneFetchGetInitLoanProposal = false;
            })
            .addCase(fetchGetInitLoanProposal.fulfilled, (state, action) => {
                delete state.queue.getInitLoanProposal;
                state.status = 'succeeded';
                state.isDoneFetchGetInitLoanProposal = true;

                const { resultMessage, resultCode, data } = action.payload;

                if (resultCode === '00' && data) {
                    state.error = '';
                    // sổ mở tại quầy hay online
                    state.isCounter = state.account.openMethod === COUNTER;

                    if (data?.loanPurposes.length > 0) {
                        state.loanPurpose = data.loanPurposes[0];
                    }
                    state.product = data.product;
                    state.productCode = data.product.productCode;
                    state.maxAmount = Number(data.product.maxAmount);
                    state.minAmount = Number(data.product.minAmount);
                    state.minInterestRate = Number(data.product.minInterestRate);
                    state.maxInterestRate = Number(data.product.maxInterestRate);
                    state.interestConfigs = data.product.interestConfigs;

                    state.customerInfo = data.customerInfo;
                    state.phoneNumber = data.customerInfo.phoneNumber;
                    state.email = data.customerInfo.emailAddress;
                    state.paymentAcct = data.paymentAcct;

                    state.branchId = data.branchId;
                    if (data.branches.length > 0) {
                        state.branchSelected = data.branches.find((item) => item.branch === data.branchId) || {};
                    }

                    state.intRate = data.intRate;
                    state.availableOutstanding = Number(data.availableOutstanding);
                    state.maturityDate = data.maturityDate;
                    state.disbursementDate = data.disbursementDate;

                    // check condition date
                    if (data.disbursementDate > data.maturityDate) {
                        state.error = 'Thời gian vay nhỏ hơn quy định của sản phẩm. Vui lòng kiểm tra lại hoặc chọn sổ tiết kiệm khác dùng để vay.';
                        // state.isShowModal = true;
                    }

                    // subDate = maturityDate - disbursementDate
                    state.subDate = moment(moment(data.maturityDate, 'YYYY-MM-DD HH:mm:ss')).diff(moment(data.disbursementDate, 'YYYY-MM-DD HH:mm:ss'), 'days');
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchGetInitLoanProposal.rejected, (state, action) => {
                delete state.queue.getInitLoanProposal;
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch GetInitLoanProposal';
                state.isDoneFetchGetInitLoanProposal = true;
            })
            // -----------------------------------------------------------------
            // fetchGetListCurrentAccounts
            // -----------------------------------------------------------------
            .addCase(fetchGetListCurrentAccounts.pending, (state) => {
                state.queue.getListCurrentAccounts = 'getListCurrentAccounts';
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchGetListCurrentAccounts.rejected, (state, action) => {
                delete state.queue.getListCurrentAccounts;
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch getListCurrentAccounts';
            })
            .addCase(fetchGetListCurrentAccounts.fulfilled, (state, { payload }) => {
                delete state.queue.getListCurrentAccounts;
                state.status = 'succeeded';
                const { resultMessage, resultCode, data } = payload;
                if (resultCode === '00' && data) {
                    state.error = '';
                    state.currentAccounts = data.accounts;
                } else {
                    state.error = resultMessage;
                }
            })
            // -----------------------------------------------------------------
            // fetchGenerateContract
            // -----------------------------------------------------------------
            .addCase(fetchGenerateContract.pending, (state) => {
                state.queue.generateContract = 'generateContract';
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchGenerateContract.fulfilled, (state, action) => {
                delete state.queue.generateContract;
                state.status = 'succeeded';
                state.api.generateContract = action.payload;
                const { resultMessage, resultCode, data } = action.payload;
                if (resultCode === '00' && data) {
                    state.error = '';
                    state.pdfBase64 = data.pdfBase64;
                    state.contractNo = data.contractNo;
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchGenerateContract.rejected, (state, action) => {
                delete state.queue.generateContract;
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to search product status';
            })
            // -----------------------------------------------------------------
            // fetchInitLoanProposal
            // -----------------------------------------------------------------
            .addCase(fetchInitLoanProposal.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchInitLoanProposal.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.api.initLoanProposal = action.payload;
                const { data, resultCode, resultMessage } = action.payload;
                //success
                if (resultCode === '00' && data) {
                    state.error = '';
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchInitLoanProposal.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to search product status';
            })
            // -----------------------------------------------------------------
            // fetchSubmitLoanProposal
            // -----------------------------------------------------------------
            .addCase(fetchSubmitLoanProposal.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchSubmitLoanProposal.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.api.submitLoanProposal = action.payload;
                if (action.payload.resultCode === '00') {
                    //success
                    state.error = '';
                } else {
                    state.error = action.payload.resultMessage;
                }
            })
            .addCase(fetchSubmitLoanProposal.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to search product status';
            })
            // -----------------------------------------------------------------
            // fetchProductStatus
            // -----------------------------------------------------------------
            .addCase(fetchProductStatus.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchProductStatus.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.api.productStatus = action.payload;
                const { data, resultCode, resultMessage } = action.payload;
                if (resultCode === '00' && data) {
                    state.error = '';
                    const { status, productStatus, remainingLimit } = data;
                    if (status === 'ON') {
                        if (productStatus === false) {
                            const remAMT = Number(remainingLimit) < 0 ? 0 : Number(remainingLimit);
                            // state.loanAmount = remAMT;
                            slice.caseReducers.setLoanAmount(state, { type: 'setLoanAmount', payload: remAMT });
                            state.error = `Số tiền tối đa có thể vay theo chính sách sản phẩm là ${remAMT === 0 ? 0 : formatMoney(remAMT)} đồng`;
                        }
                    } else {
                        state.error = 'Rất tiếc, dịch vụ vay cầm cố chưa khả dụng lúc này';
                    }
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchProductStatus.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch productStatus';
            })
            // -----------------------------------------------------------------
            // fetchResendOTP
            // -----------------------------------------------------------------
            .addCase(fetchResendOTP.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchResendOTP.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.api.resendOTP = action.payload;

                const { data, resultCode, resultMessage } = action.payload;
                if (resultCode === '00' && data) {
                    state.error = '';
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchResendOTP.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch resend OTP';
            });
    },
});

export default slice;
