import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { ICmsLoanRegisterTnCRepository } from '@src/domain/interfaces/cms/loan_register/loanRegisterTnC';

export class GetCmsLoanRegisterTnCHandler {
    private readonly _cmsLoanRegisterTnCRepository: ICmsLoanRegisterTnCRepository;

    constructor(
        @inject(TYPES.ICmsLoanRegisterTnCRepository) CmsLoanRegisterTnCRepository: ICmsLoanRegisterTnCRepository,
    ) {
        this._cmsLoanRegisterTnCRepository = CmsLoanRegisterTnCRepository;
    }

    handle(segment: string) {
        return this._cmsLoanRegisterTnCRepository.getCmsLoanRegisterTnC(segment)
    }
}