import { createAsyncThunk } from '@reduxjs/toolkit';
import { GetLocationHandler } from '@src/application/location/queries/get_location/get_location_handler';
import { container } from '@src/di/inversify.config';
import { TYPES } from '@src/di/types/types';

export const fetchLocationDetail = createAsyncThunk(
  'location/search',
  async (request: string) => {
    const location = container.get<GetLocationHandler>(
      TYPES.GetLocationHandler,
    );
    return await location.handle(request);
  },
);
