import React, { useEffect } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';

import { useDispatch, useSelector } from '@src/lib/redux';
import {
  selectWeather,
  selectWeatherError,
  selectWeatherStatus,
} from '../selector';
import { selectLocation } from '../../WeatherSearch/selector';
import { fetchWeather } from '../thunk';

export const WeatherInfo: React.FC = () => {
  const dispatch = useDispatch();

  const weather = useSelector(selectWeather);
  const status = useSelector(selectWeatherStatus);
  const error = useSelector(selectWeatherError);
  const location = useSelector(selectLocation);

  useEffect(() => {
    dispatch(
      fetchWeather({
        latitude: location?.latitude ?? 0,
        longitude: location?.longitude ?? 0,
      }),
    );
  }, [dispatch, location]);

  if (status === 'loading') {
    return <ActivityIndicator />;
  }

  if (error) {
    return <Text style={styles.error}>{error}</Text>;
  }

  if (status === 'succeeded') {
    return (
      <View style={styles.weatherInfo}>
        <Text style={styles.temperature}>{weather?.temperature}°C</Text>
        <Text style={styles.windInfo}>
          Wind: {weather?.windspeed} km/h, Direction: {weather?.winddirection}°
        </Text>
      </View>
    );
  }

  return <View />;
};

const styles = StyleSheet.create({
  weatherInfo: {
    backgroundColor: '#f5f5f5',
    borderRadius: 8,
    padding: 20,
    width: '100%',
    maxWidth: 350,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.5,
    elevation: 5,
  },
  temperature: {
    fontSize: 36,
    fontWeight: 'bold',
    color: '#000000',
  },
  windInfo: {
    fontSize: 16,
    color: '#555',
    marginTop: 8,
  },
  statusText: {
    fontSize: 18,
    color: '#333',
    textAlign: 'center',
    marginTop: 20,
  },
  error: {
    fontSize: 18,
    color: 'red',
    textAlign: 'center',
    marginTop: 20,
  },
});

export default styles;
