import { injectable } from 'inversify';
import { IInitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/init_loan_proposal';
import { InitLoanProposalResponse } from '@src/domain/entities/loan_collateral/init_loan_proposal';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { InitLoanProposalPayload } from '@src/application/loan_collateral/queries/init_loan_proposal/init_loan_proposal_query';
import uuid from 'react-native-uuid';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class InitLoanProposalRepository extends HttpService implements IInitLoanProposalRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async initLoanProposal(query: InitLoanProposalPayload): Promise<InitLoanProposalResponse> {
        const request = query as unknown as InitLoanProposalPayload;
        const url = '/initLoanProposal';
        const dataReq = {
            ...request,
            requestId: uuid.v4(),
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        return data as InitLoanProposalResponse;
    }
}
